beforeSaveCustomScript:
// Zest: completa la Categoría con la "Prioridad A/B/C" que trae la descripción.
// Solo si está vacía: una categoría puesta a mano no se pisa.
if (!categoria && description) {
    if (string\contains(description, 'Prioridad A')) {
        categoria = 'A';
    } else if (string\contains(description, 'Prioridad B')) {
        categoria = 'B';
    } else if (string\contains(description, 'Prioridad C')) {
        categoria = 'C';
    }
}
